package llamaserver_test

import (
	"context"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"testing"

	agent "github.com/easel/fizeau/internal/core"
	"github.com/easel/fizeau/internal/provider/llamaserver"
	"github.com/easel/fizeau/internal/provider/openai"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// TestLlamaserver_EnableThinking_WireBody verifies that when thinking is
// enabled on llamaserver (Qwen-format), the request body nests enable_thinking
// and thinking_budget inside chat_template_kwargs envelope, not at the top level.
// ADR-010 amendment §7 specifies this: top-level enable_thinking is silently
// dropped by llama-server; the kwargs envelope is required.
func TestLlamaserver_EnableThinking_WireBody(t *testing.T) {
	const model = "Qwen3.6-27B-UD-Q3_K_XL.gguf"

	var capturedBody []byte
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		capturedBody = body
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{
			"id":"chatcmpl-1",
			"model":"` + model + `",
			"choices":[{"index":0,"message":{"role":"assistant","content":"done"},"finish_reason":"stop"}],
			"usage":{"prompt_tokens":12,"completion_tokens":5,"total_tokens":17}
		}`))
	}))
	defer srv.Close()

	// Create llamaserver provider with Qwen thinking format
	p := llamaserver.New(llamaserver.Config{
		BaseURL:  srv.URL + "/v1",
		APIKey:   "test",
		Model:    model,
	})

	// Chat with thinking enabled
	_, err := p.Chat(context.Background(), []agent.Message{{Role: agent.RoleUser, Content: "hello"}}, nil, agent.Options{Reasoning: agent.ReasoningTokens(4096)})
	require.NoError(t, err)

	// Verify wire format
	var reqBody map[string]interface{}
	require.NoError(t, json.Unmarshal(capturedBody, &reqBody))

	// AC1a: enable_thinking must NOT be at top level
	assert.NotContains(t, reqBody, "enable_thinking",
		"enable_thinking must not be at top level; must use chat_template_kwargs envelope: %s", string(capturedBody))

	// AC1b: thinking_budget must NOT be at top level
	assert.NotContains(t, reqBody, "thinking_budget",
		"thinking_budget must not be at top level; must use chat_template_kwargs envelope: %s", string(capturedBody))

	// AC1c: chat_template_kwargs must exist and contain enable_thinking=true
	ctk, ok := reqBody["chat_template_kwargs"].(map[string]interface{})
	require.True(t, ok, "request body must include chat_template_kwargs: %s", string(capturedBody))
	assert.Equal(t, true, ctk["enable_thinking"],
		"chat_template_kwargs.enable_thinking must be true when thinking is enabled: %s", string(capturedBody))

	// AC1d: thinking_budget must be in the envelope
	assert.Equal(t, float64(4096), ctk["thinking_budget"],
		"chat_template_kwargs.thinking_budget must be 4096: %s", string(capturedBody))
}

// TestLlamaserver_EnableThinking_Disabled verifies that when thinking is
// explicitly disabled on llamaserver (Qwen-format), the wire format correctly
// emits chat_template_kwargs.enable_thinking=false per ADR-010 §9'.
func TestLlamaserver_EnableThinking_Disabled(t *testing.T) {
	const model = "Qwen3.6-27B-UD-Q3_K_XL.gguf"

	var capturedBody []byte
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		capturedBody = body
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{
			"id":"chatcmpl-1",
			"model":"` + model + `",
			"choices":[{"index":0,"message":{"role":"assistant","content":"done"},"finish_reason":"stop"}],
			"usage":{"prompt_tokens":12,"completion_tokens":5,"total_tokens":17}
		}`))
	}))
	defer srv.Close()

	// Create llamaserver provider with Qwen thinking format
	p := llamaserver.New(llamaserver.Config{
		BaseURL:  srv.URL + "/v1",
		APIKey:   "test",
		Model:    model,
	})

	// Chat with thinking explicitly disabled
	_, err := p.Chat(context.Background(), []agent.Message{{Role: agent.RoleUser, Content: "hello"}}, nil, agent.Options{Reasoning: agent.ReasoningOff})
	require.NoError(t, err)

	// Verify wire format
	var reqBody map[string]interface{}
	require.NoError(t, json.Unmarshal(capturedBody, &reqBody))

	// AC3a: enable_thinking must NOT be at top level
	assert.NotContains(t, reqBody, "enable_thinking",
		"enable_thinking must not be at top level; must use chat_template_kwargs envelope: %s", string(capturedBody))

	// AC3b: chat_template_kwargs must exist and contain enable_thinking=false
	ctk, ok := reqBody["chat_template_kwargs"].(map[string]interface{})
	require.True(t, ok, "request body must include chat_template_kwargs when thinking is disabled: %s", string(capturedBody))
	assert.Equal(t, false, ctk["enable_thinking"],
		"chat_template_kwargs.enable_thinking must be false when thinking is disabled: %s", string(capturedBody))

	// AC3c: thinking_budget should not be present when disabled
	_, hasBudget := ctk["thinking_budget"]
	assert.False(t, hasBudget,
		"chat_template_kwargs.thinking_budget must not be present when thinking is disabled: %s", string(capturedBody))
}
